package dev.livingrealms.minecraft.entity;import java.util.*;import java.util.concurrent.ConcurrentHashMap;public final class AircraftProjectionIndex{private static final Map<UUID,LivingRealmsAircraftEntity> BY_UUID=new ConcurrentHashMap<>();private AircraftProjectionIndex(){}public static void joined(LivingRealmsAircraftEntity e){BY_UUID.put(e.getUUID(),e);}public static void left(LivingRealmsAircraftEntity e){BY_UUID.remove(e.getUUID());}public static Collection<LivingRealmsAircraftEntity> loaded(){return List.copyOf(BY_UUID.values());}public static LivingRealmsAircraftEntity forSlot(long wing,int slot){return BY_UUID.values().stream().filter(e->e.wingId()==wing&&e.projectionSlot()==slot&&!e.isRemoved()).findFirst().orElse(null);}public static void clear(){BY_UUID.clear();}}
